{
  "background_need": "Kahdeksan kuvitteellisen pienyrityksen työntekijät ja yrittäjät haluavat kokeilla tekoälyä arjen tehtävissä, mutta osaaminen ja tietosuojakäytännöt vaihtelevat. Pilotissa saa käyttää vain synteettisiä tietoja.",
  "objectives": [
    {
      "id": "O1",
      "description": "Yritykset tunnistavat yhden hyödyllisen ja turvallisesti rajatun tekoälykokeilun."
    },
    {
      "id": "O2",
      "description": "Yritykset arvioivat kokeilun vaikutuksia."
    }
  ],
  "target_groups": [
    "Kuvitteellisten pienyritysten työntekijät",
    "Kuvitteellisten pienyritysten yrittäjät"
  ],
  "preliminary_activities": [
    {
      "id": "A1",
      "description": "Synteettisten tietojen laadun ja käytännön rajoitusten määrittely.","objective_ids": ["O1"]
    },
    {
      "id": "A2",
      "description": "Rajoitetun tekoälykäytön toteuttaminen kahdeksassa kuvitteellisessa yrityksessä.",
      "objective_ids": ["O1", "O2"]
    },
    {
      "id": "A3",
      "description": "Hyödyllisyyden ja turvallisuuden arviointi määritellyin kriteerein.",
      "objective_ids": ["O2"]
    }
  ],
  "expected_results": [
    {
      "id": "R1",
      "description": "Yrityksillä on konkreettinen tekoälykokeilu, joka ei vaadi todellisia asiakastietoja.",
      "activity_ids": ["A2"]
    },
    {
      "id": "R2",
      "description": "Yritykset ovat tehneet päätöksen kokeilun hyödyllisyydestä ja turvallisuudesta.",
      "activity_ids": ["A3"]
    },
    {
      "id": "R3",
      "description": "Osaamispajalla on vahvistettu rooli tietosuojan varmistamisessa synteettisten tietojen käytössä.",
      "activity_ids": ["A1", "A2"]
    }
  ],
  "proposed_indicators": [
    {
      "id": "I1",
      "description": "Yritykset ovat valinneet kokeilun hyödylliseksi.",
      "result_ids": ["R2"],
      "measurement_method": "Kyselylomake, jossa yrityksen johto merkitsee 'Hyödyllinen' vai 'Ei hyödyllinen'.\nUnit: Yritysten lukumäärä.\nUnique counting/denominator: Osallistuvien yritysten kokonaismäärä (8).\nObservable criterion: Vastaus on 'Hyödyllinen'.\nTiming: Kokeilun päätyttyä."
    },
    {
      "id": "I2",
      "description": "Yritykset ovat tunnistaneet kokeilun turvalliseksi.",
      "result_ids": ["R2"],
      "measurement_method": "Kyselylomake, jossa yrityksen johto merkitsee 'Turvallinen' vai 'Ei turvallinen'.\nUnit: Yritysten lukumäärä.\nUnique counting/denominator: Osallistuvien yritysten kokonaismäärä (8).\nObservable criterion: Vastaus on 'Turvallinen'.\nTiming: Kokeilun päätyttyä."
    },
    {
      "id": "I3",
      "description": "Synteettiset tiedot ovat täyttäneet määritellyt laatuvaatimukset.",
      "result_ids": ["R1"],
      "measurement_method": "Laadunvarmistusraportti, jossa tarkistetaan tietojen syntyä ja käyttöön soveltuvuutta.\nUnit: Tiedostojen lukumäärä.\nUnique counting/denominator: Käytettyjen tiedostojen kokonaismäärä.\nObservable criterion: Raportissa on merkintä 'Vaatimukset täytetyt'.\nTiming: Kokeilun alussa ja päätyttyä."
    }
  ],
  "assumptions": [
    "Kuvitteelliset yritykset noudattavat tietosuojalakeja, jotka sallivat synteettisten tietojen käytön.",
    "Osallistujilla on riittävä osaaminen käyttää tekoälytyökaluja ilman ohjausta.",
    "Rahoitusohjelma valitaan ennen projektin aloittamista."
  ],
  "open_questions": [
    "Mikä on tarkka määritelmä synteettisten tietojen laadulle ja rajoituksille?",
    "Kuinka varmistetaan, että kuvitteelliset yritykset eivät sekoita kokeilun tietoja todellisiin asiakastietoihin?",
    "Mitkä ovat konkreettiset arviointikriteerit hyödyllisyyden mittaamiseen?"
  ]
}

{
  "findings": [
    {
      "reference": "O1, A2",
      "observation": "Objectives O1 and A2 imply a decision on utility ('hyödyllinen') before the activity A2 is completed.",
      "evidence_quote": "\"Yritykset tunnistavat yhden hyödyllisen ja turvallisesti rajatun tekoälykokeilun...\"",
      "severity": "major"
    },
    {
      "reference": "I1, I2",
      "observation": "Indicators I1 and I2 rely on a single binary choice ('Hyödyllinen'/'Ei hyödyllinen') without distinguishing degrees of utility or specific benefits.",
      "evidence_quote": "\"Kyselylomake, jossa yrityksen johto merkitsee 'Hyödyllinen' vai 'Ei hyödyllinen'.\"",
      "severity": "minor"
    },
    {
      "reference": "A2",
      "observation": "Activity A2 assumes participants have sufficient competence to use AI tools without guidance.",
      "evidence_quote": "\"Osallistujilla on riittävä osaaminen käyttää tekoälytyökaluja ilman ohjausta.\"",
      "severity": "question"
    },
    {
      "reference": "R3",
      "observation": "Result R3 describes a role confirmation but lacks a measurable indicator to verify the outcome.",
      "evidence_quote": "\"Osaamispajalla on vahvistettu rooli tietosuojan varmistamisessa synteettisten tietojen käytössä.\"",
      "severity": "major"
    }
  ],
  "suggested_improvements": [
    "Revise Objective O1 to reflect the identification of utility *after* Activity A2, or split into two objectives: one for execution and one for evaluation.",
    "Expand Indicator I1 and I2 options to include a scale (e.g., 'Hyödyllinen', 'Osittain hyödyllinen', 'Ei hyödyllinen') to capture nuanced feedback.",
    "Add a preliminary activity or assumption revision requiring a competence assessment before Activity A2 begins.",
    "Create Indicator I4 specifically for Result R3, such as 'Osaamispaja on vahvistanut tietosuojan varmistamisroolin' measured by a signed confirmation document."
  ]
}

